#!/usr/bin/env node

/**
 * ShowItGlo — development seed.
 *
 * Creates a small, HONEST dataset: three obviously-fake demo users, six posts
 * that start at exactly zero, and real backing generated by driving
 * store.recordInteraction — so wallets, ledgers, post totals and the board all
 * reconcile the way they would in production.
 *
 * What this script deliberately does NOT do:
 *   * invent raised amounts, backer counts or like counts
 *   * name, impersonate or attribute anything to a real company or person
 *   * create brand responses (a real brand must publish those itself)
 *
 * Usage:
 *   DATABASE_URL="postgresql://user@localhost:5432/showitglo_dev" node scripts/seed-dev.mjs
 *
 * Refuses to run against NODE_ENV=production unless DEMO_SEED=1 is set.
 * Re-running is safe: it detects the demo users and exits without touching
 * anything.
 */

import { existsSync, mkdirSync, readFileSync } from 'fs';
import { createRequire } from 'module';
import { spawnSync } from 'child_process';
import { dirname, resolve } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(__dirname, '..');
const require = createRequire(import.meta.url);

// --------------------------------------------------------------------------
// Environment
// --------------------------------------------------------------------------

function loadDotEnv() {
  for (const envPath of [resolve(repoRoot, '.env.local'), resolve(repoRoot, '.env')]) {
    if (!existsSync(envPath)) continue;
    try {
      for (const line of readFileSync(envPath, 'utf8').split('\n')) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#') || !trimmed.includes('=')) continue;
        const [k, ...v] = trimmed.split('=');
        const key = k.trim();
        if (!process.env[key]) process.env[key] = v.join('=').trim().replace(/^["']|["']$/g, '');
      }
    } catch {
      /* ignore unreadable env files */
    }
  }
}

loadDotEnv();

if (process.env.NODE_ENV === 'production' && process.env.DEMO_SEED !== '1') {
  console.error('\n❌ Refusing to seed a production environment.');
  console.error('   Set DEMO_SEED=1 if you genuinely intend to write demo data there.\n');
  process.exit(1);
}

if (!process.env.DATABASE_URL) {
  console.error('\n❌ DATABASE_URL is not set.\n');
  console.error('  DATABASE_URL="postgresql://user@localhost:5432/showitglo_dev" node scripts/seed-dev.mjs\n');
  process.exit(1);
}

// --------------------------------------------------------------------------
// Load the real store (compiled from TypeScript so the seed exercises the same
// money code paths the app does, rather than a duplicate written in SQL).
// --------------------------------------------------------------------------

function loadStore() {
  // Must live inside the repo so the compiled CJS resolves `pg` from
  // ./node_modules; node_modules/.cache is already git-ignored.
  const outDir = resolve(repoRoot, 'node_modules/.cache/showitglo-store');
  const tsc = resolve(repoRoot, 'node_modules/.bin/tsc');

  if (!existsSync(tsc)) {
    console.error('\n❌ typescript is not installed. Run `npm install` first.\n');
    process.exit(1);
  }

  mkdirSync(outDir, { recursive: true });

  const result = spawnSync(
    tsc,
    [
      resolve(repoRoot, 'src/lib/db/store.ts'),
      '--outDir', outDir,
      '--rootDir', resolve(repoRoot, 'src/lib'),
      '--module', 'commonjs',
      '--moduleResolution', 'node',
      '--target', 'es2022',
      '--esModuleInterop',
      '--skipLibCheck',
      '--resolveJsonModule',
    ],
    { cwd: repoRoot, stdio: 'inherit' }
  );

  if (result.status !== 0) {
    console.error('\n❌ Could not compile src/lib/db/store.ts.\n');
    process.exit(1);
  }

  return require(resolve(outDir, 'db/store.js'));
}

