// --------------------------------------------------------------------------
// Seed
// --------------------------------------------------------------------------

async function main() {
  const store = loadStore();

  console.log('\n🌱 ShowItGlo — development seed');

  const existing = await store.getUser(ADA.id);
  if (existing) {
    console.log('   demo data already present — nothing to do.');
    console.log('   (drop and re-init the database to reseed)\n');
    return;
  }

  const category = await store.getCategory('global');
  if (!category) {
    throw new Error('The "global" category is missing. Run `node scripts/init-db.mjs` first.');
  }

  // 1. Users + wallets. The balance arrives through the same credit path a
  //    real Stripe top-up uses, so the ledger reconciles to the balance.
  for (const user of DEMO_USERS) {
    await store.upsertUser({
      id: user.id,
      email: `devseed_${user.id}@anon.showitglo.local`,
      email_verified_at: null,
      alias: user.alias,
      is_profile_public: true,
      brand_verified_at: null,
      stripe_customer_id: null,
      role: 'user',
      status: 'active',
      notif_prefs: { inapp: true, email: false, push: false, outbid_digest: true },
      created_at: new Date().toISOString(),
      deleted_at: null,
    });

    await store.creditWalletFromPayment({
      userId: user.id,
      amountCents: user.topupCents,
      paymentIntentId: `pi_devseed_${user.id}`,
      currency: 'usd',
    });
  }
  console.log(`   ${DEMO_USERS.length} demo users + funded wallets ✓`);

  // 2. Posts. Every counter starts at zero — nothing is pre-inflated.
  for (const post of DEMO_POSTS) {
    await store.createPost({
      id: post.id,
      slug: post.slug,
      author_id: post.author.id,
      category_id: 'global',
      kind: post.kind,
      title: post.title,
      body: post.body,
      media_url: null,
      is_ad: false,
      demand_target: post.demandTarget ?? null,
      demand_target_user_id: null,
      counter_of: post.counterOf ?? null,
      source_url: null,
      source_platform: null,
      author_display: post.author.alias,
      status: 'live',
      score_base: 0,
      total_raised_cents: 0,
      backers_count: 0,
      like_units: 0,
      streak_days: 0,
    });
  }
  console.log(`   ${DEMO_POSTS.length} posts at zero ✓`);

  // 3. Real backing through the real transaction.
  let spentCents = 0;
  for (const backing of DEMO_BACKINGS) {
    const post = DEMO_POSTS[backing.post];
    await store.recordInteraction({
      postId: post.id,
      userId: backing.user.id,
      kind: backing.kind,
      units: backing.units,
      amountCents: backing.cents,
      visibility: 'alias',
      payerDisplay: backing.user.alias,
      idempotencyKey: `devseed:${post.id}:${backing.user.id}:${backing.kind}`,
    });
    spentCents += backing.cents;
  }
  console.log(`   ${DEMO_BACKINGS.length} backings totalling $${(spentCents / 100).toFixed(2)} ✓`);

  // 4. Debates wired to the posts above.
  for (const entry of DEMO_DEBATES) {
    await store.createDebate(
      { ...entry.debate, created_at: new Date().toISOString() },
      entry.sides.map((side) => ({
        debate_id: entry.debate.id,
        side_key: side.side_key,
        label: side.label,
        post_id: DEMO_POSTS[side.post].id,
      }))
    );

    for (const opinion of entry.opinions) {
      await store.addDebateOpinion({
        debateId: entry.debate.id,
        sideKey: opinion.side_key,
        authorName: opinion.author,
        text: opinion.text,
        isPaid: false,
        amountCents: 0,
      });
    }
  }
  console.log(`   ${DEMO_DEBATES.length} debates ✓`);

  // 5. Report what the board actually looks like now.
  const board = await store.getRankedBoard('global', { limit: 10 });
  console.log('\n   board:');
  for (const row of board) {
    console.log(
      `     #${row.rank}  $${row.display_score.toFixed(2).padStart(6)}  ` +
        `${row.backers_count} backer(s)  ${row.title.slice(0, 52)}`
    );
  }

  const wallets = await Promise.all(DEMO_USERS.map((u) => store.getWallet(u.id)));
  console.log('\n   wallets:');
  for (let i = 0; i < DEMO_USERS.length; i++) {
    const w = wallets[i];
    console.log(
      `     ${DEMO_USERS[i].alias.padEnd(18)} balance $${(w.balance_cents / 100).toFixed(2)}  ` +
        `spent $${(w.lifetime_spend_cents / 100).toFixed(2)}`
    );
  }

  console.log('\n✅ Seed complete.\n');
}

main()
  .then(() => process.exit(0))
  .catch((err) => {
    console.error(`\n❌ Seed failed: ${err.message}`);
    if (err.code) console.error(`   code: ${err.code}`);
    if (err.detail) console.error(`   detail: ${err.detail}`);
    console.error('');
    process.exit(1);
  });
